//! Host-neutral application core for the Prior Authorization Workbench.
//!
//! Every surface — Axum web, Tauri desktop, Flutter mobile — consumes the same
//! [`AppServices`]. This crate names no shell: no Axum, no Tauri, no FFI. That
//! constraint is what lets one core serve three surfaces, and it is checked by
//! `scripts/audit.sh`.
//!
//! The domain types below carry the clinical invariants from
//! `docs/design/schema/schema.sql`. Where the database enforces a rule with a
//! trigger, the type system mirrors it, so a violation is a compile error on
//! the way to being a runtime refusal.

pub mod affirmation;
pub mod domain;
pub mod ports;
pub mod reassessment;
pub mod session;
pub mod signing;

use std::sync::Arc;

/// The single capability surface every shell consumes.
///
/// Shells wire adapters into the ports; they never reach past this struct into
/// a repository or a provider directly.
#[derive(Clone)]
pub struct AppServices {
    pub cases: Arc<dyn ports::CaseRepository>,
    pub evidence: Arc<dyn ports::EvidenceRepository>,
    pub criteria: Arc<dyn ports::CriteriaRepository>,
    pub letters: Arc<dyn ports::LetterRepository>,
    pub authority: Arc<dyn ports::AuthorityPort>,
    pub clock: Arc<dyn ports::Clock>,
    pub sessions: Arc<dyn session::SessionPort>,
}

impl AppServices {
    /// Affirm one of the four surgeon-gate confirmations.
    ///
    /// The capability check happens here AND in the database. That is not
    /// redundancy for its own sake: a service role can bypass row-level
    /// security, so the database trigger is the floor, and this check is what
    /// gives the caller a typed error instead of a constraint violation.
    pub async fn affirm_gate(
        &self,
        actor: domain::ActorId,
        case_id: domain::CaseId,
        kind: domain::GateAffirmationKind,
    ) -> Result<domain::GateState, domain::DomainError> {
        if !self
            .authority
            .holds(actor, domain::Capability::AffirmGate)
            .await?
        {
            return Err(domain::DomainError::CapabilityDenied {
                capability: domain::Capability::AffirmGate,
                actor,
            });
        }
        self.cases
            .record_affirmation(case_id, kind, actor, self.clock.now())
            .await
    }
}

//! Outbound ports. The core depends on these traits; adapters implement them.
//!
//! Nothing here names a database, an HTTP client, or a shell. A Postgres
//! adapter and an in-memory test adapter are interchangeable from the core's
//! point of view, which is what makes the core testable without a container.

use crate::domain::*;
use async_trait::async_trait;

#[async_trait]
pub trait CaseRepository: Send + Sync {
    /// Legacy adapters cannot silently accept authenticated durable commands.
    async fn execute_gate_command(
        &self,
        _: &crate::affirmation::ClinicalContext,
        _: &crate::affirmation::GateCommand,
    ) -> Result<crate::affirmation::GateCommandResult, crate::affirmation::GateError> {
        Err(crate::affirmation::GateError::Unavailable)
    }

    async fn read_verified_gate(
        &self,
        _: &crate::affirmation::ClinicalContext,
        _: uuid::Uuid,
    ) -> Result<crate::affirmation::GateSnapshot, crate::affirmation::GateError> {
        Err(crate::affirmation::GateError::Unavailable)
    }

    async fn lookup_gate_command(
        &self,
        _: &crate::affirmation::ClinicalContext,
        _: uuid::Uuid,
    ) -> Result<Option<crate::affirmation::GateCommandResult>, crate::affirmation::GateError> {
        Err(crate::affirmation::GateError::Unavailable)
    }

    async fn gate_state(&self, case_id: CaseId) -> Result<GateState, DomainError>;

    async fn record_affirmation(
        &self,
        case_id: CaseId,
        kind: GateAffirmationKind,
        actor: ActorId,
        at: chrono::DateTime<chrono::Utc>,
    ) -> Result<GateState, DomainError>;
}

#[async_trait]
pub trait EvidenceRepository: Send + Sync {
    async fn read_reassessment_target(
        &self,
        _: &crate::affirmation::ClinicalContext,
        _: uuid::Uuid,
        _: uuid::Uuid,
    ) -> Result<
        crate::reassessment::EvidenceReassessmentTarget,
        crate::reassessment::ReassessmentError,
    > {
        Err(crate::reassessment::ReassessmentError::Unavailable)
    }

    async fn execute_reassessment(
        &self,
        _: &crate::affirmation::ClinicalContext,
        _: &crate::reassessment::ReassessEvidenceCommand,
    ) -> Result<crate::reassessment::ReassessEvidenceResult, crate::reassessment::ReassessmentError>
    {
        Err(crate::reassessment::ReassessmentError::Unavailable)
    }

    async fn lookup_reassessment_command(
        &self,
        _: &crate::affirmation::ClinicalContext,
        _: uuid::Uuid,
    ) -> Result<
        Option<crate::reassessment::ReassessEvidenceResult>,
        crate::reassessment::ReassessmentError,
    > {
        Err(crate::reassessment::ReassessmentError::Unavailable)
    }

    /// Counts by state, which is what the dashboard tiles read. Returned as a
    /// triple rather than a map so a caller cannot forget that `Void` exists.
    async fn counts(&self, case_id: CaseId) -> Result<EvidenceCounts, DomainError>;
}

#[derive(Debug, Clone, Copy, Default, serde::Serialize, serde::Deserialize)]
pub struct EvidenceCounts {
    pub met: u32,
    pub gap: u32,
    pub void: u32,
}

#[async_trait]
pub trait CriteriaRepository: Send + Sync {
    async fn get(&self, id: CriterionId) -> Result<Criterion, DomainError>;

    /// Live criteria for a payer, ranked by grade and recency decay.
    async fn live_for_payer(&self, payer: &str) -> Result<Vec<Criterion>, DomainError>;
}

#[derive(Debug, Clone, serde::Serialize, serde::Deserialize)]
pub struct Criterion {
    pub id: CriterionId,
    pub label: String,
    pub requirement: String,
    pub grade: EvidenceGrade,
    /// Blended similarity × grade × recency. A two-year-old derived rule sinks
    /// below current published policy rather than tying with it.
    pub retrieval_weight: f32,
}

#[async_trait]
pub trait LetterRepository: Send + Sync {
    /// Legacy adapters refuse verified signing until they implement the
    /// authoritative clinical transaction.
    async fn read_signing_target(
        &self,
        _: &crate::affirmation::ClinicalContext,
        _: LetterId,
    ) -> Result<crate::signing::SigningTarget, crate::signing::SigningError> {
        Err(crate::signing::SigningError::Unavailable)
    }

    async fn execute_sign_letter(
        &self,
        _: &crate::affirmation::ClinicalContext,
        _: &crate::signing::SignLetterCommand,
    ) -> Result<crate::signing::SignLetterResult, crate::signing::SigningError> {
        Err(crate::signing::SigningError::Unavailable)
    }

    async fn lookup_sign_letter_command(
        &self,
        _: &crate::affirmation::ClinicalContext,
        _: uuid::Uuid,
    ) -> Result<Option<crate::signing::SignLetterResult>, crate::signing::SigningError> {
        Err(crate::signing::SigningError::Unavailable)
    }

    async fn get(&self, id: LetterId) -> Result<Letter, DomainError>;

    /// Retrieved criteria that are not citable as policy and have neither been
    /// attributed nor explicitly excluded by the surgeon. Signing is blocked
    /// while this is non-empty.
    async fn unresolved_non_policy_retrievals(
        &self,
        id: LetterId,
    ) -> Result<Vec<CriterionId>, DomainError>;

    async fn sign(
        &self,
        id: LetterId,
        actor: ActorId,
        at: chrono::DateTime<chrono::Utc>,
    ) -> Result<Letter, DomainError>;
}

/// Resolves capabilities for an actor.
///
/// Backed by the gateway's policy decision in production. An AI assistant
/// acting for a surgeon is a *different principal* and resolves to a different
/// capability set — it does not inherit the surgeon's clinical authority.
#[async_trait]
pub trait AuthorityPort: Send + Sync {
    /// The existing actor-only scaffold grants no verified clinical authority.
    async fn may_affirm_gate(
        &self,
        _: &crate::affirmation::ClinicalContext,
        _: uuid::Uuid,
    ) -> Result<bool, crate::affirmation::GateError> {
        Ok(false)
    }

    async fn may_sign_letter(
        &self,
        _: &crate::affirmation::ClinicalContext,
        _: LetterId,
    ) -> Result<bool, crate::signing::SigningError> {
        Ok(false)
    }

    async fn may_reassess_evidence(
        &self,
        _: &crate::affirmation::ClinicalContext,
        _: uuid::Uuid,
        _: uuid::Uuid,
    ) -> Result<bool, crate::reassessment::ReassessmentError> {
        Ok(false)
    }

    async fn holds(&self, actor: ActorId, capability: Capability) -> Result<bool, DomainError>;
}

/// Injected so tests can pin time rather than sleep.
pub trait Clock: Send + Sync {
    fn now(&self) -> chrono::DateTime<chrono::Utc>;
}

pub struct SystemClock;
impl Clock for SystemClock {
    fn now(&self) -> chrono::DateTime<chrono::Utc> {
        chrono::Utc::now()
    }
}

//! Verified-context evidence reassessment shared by every shell.
//! Identity, practice and clinical authority come only from [`ClinicalContext`].

use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};
use uuid::Uuid;

use crate::{AppServices, affirmation::ClinicalContext, domain::EvidenceState, session::Principal};

/// Transport input. The current assessment timestamp is the optimistic
/// concurrency boundary observed in the authorized replica.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct ReassessEvidenceMutation {
    pub command_id: Uuid,
    pub state: EvidenceState,
    pub expected_assessed_at: DateTime<Utc>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ReassessEvidenceCommand {
    pub command_id: Uuid,
    pub case_id: Uuid,
    pub evidence_id: Uuid,
    pub state: EvidenceState,
    pub expected_assessed_at: DateTime<Utc>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct EvidenceReassessmentTarget {
    pub case_id: Uuid,
    pub evidence_id: Uuid,
    pub state: EvidenceState,
    pub assessed_at: DateTime<Utc>,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct ReassessEvidenceResult {
    pub command_id: Uuid,
    pub case_id: Uuid,
    pub evidence_id: Uuid,
    pub previous_state: EvidenceState,
    pub state: EvidenceState,
    pub expected_assessed_at: DateTime<Utc>,
    pub assessed_at: DateTime<Utc>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, thiserror::Error)]
pub enum ReassessmentError {
    #[error("authentication required")]
    Unauthenticated,
    #[error("evidence reassessment denied")]
    Denied,
    #[error("evidence assessment or command not found")]
    NotFound,
    #[error("evidence assessment changed after it was reviewed")]
    RevisionConflict,
    #[error("command identifier already has a different payload")]
    CommandConflict,
    #[error("evidence reassessment service unavailable")]
    Unavailable,
    #[error("native authentication unavailable")]
    NativeAuthenticationUnavailable,
}

impl AppServices {
    fn check_reassessment_context(
        &self,
        context: &ClinicalContext,
    ) -> Result<(), ReassessmentError> {
        if context.expires_at <= self.clock.now() {
            return Err(ReassessmentError::Unauthenticated);
        }
        if context.principal != Principal::User {
            return Err(ReassessmentError::Denied);
        }
        Ok(())
    }

    fn command_matches_result(
        command: &ReassessEvidenceCommand,
        result: &ReassessEvidenceResult,
    ) -> bool {
        result.command_id == command.command_id
            && result.case_id == command.case_id
            && result.evidence_id == command.evidence_id
            && result.previous_state != result.state
            && result.state == command.state
            && result.expected_assessed_at == command.expected_assessed_at
    }

    /// Reconciles a stored result before reading mutable target state. This is
    /// what makes a lost response recoverable without replaying a clinical act.
    pub async fn execute_reassess_evidence(
        &self,
        context: &ClinicalContext,
        command: &ReassessEvidenceCommand,
    ) -> Result<ReassessEvidenceResult, ReassessmentError> {
        self.check_reassessment_context(context)?;
        if let Some(original) = self
            .evidence
            .lookup_reassessment_command(context, command.command_id)
            .await?
        {
            if !Self::command_matches_result(command, &original) {
                return Err(ReassessmentError::CommandConflict);
            }
            if !self
                .authority
                .may_reassess_evidence(context, original.case_id, original.evidence_id)
                .await?
            {
                return Err(ReassessmentError::Denied);
            }
            return Ok(original);
        }

        if !self
            .authority
            .may_reassess_evidence(context, command.case_id, command.evidence_id)
            .await?
        {
            return Err(ReassessmentError::Denied);
        }
        let target = self
            .evidence
            .read_reassessment_target(context, command.case_id, command.evidence_id)
            .await?;
        if target.case_id != command.case_id || target.evidence_id != command.evidence_id {
            return Err(ReassessmentError::Unavailable);
        }
        if target.assessed_at != command.expected_assessed_at {
            return Err(ReassessmentError::RevisionConflict);
        }
        self.check_reassessment_context(context)?;
        if !self
            .authority
            .may_reassess_evidence(context, command.case_id, command.evidence_id)
            .await?
        {
            return Err(ReassessmentError::Denied);
        }
        self.evidence.execute_reassessment(context, command).await
    }

    pub async fn read_reassessment_target(
        &self,
        context: &ClinicalContext,
        case_id: Uuid,
        evidence_id: Uuid,
    ) -> Result<EvidenceReassessmentTarget, ReassessmentError> {
        self.check_reassessment_context(context)?;
        let target = self
            .evidence
            .read_reassessment_target(context, case_id, evidence_id)
            .await?;
        if target.case_id != case_id || target.evidence_id != evidence_id {
            return Err(ReassessmentError::Unavailable);
        }
        Ok(target)
    }

    pub async fn lookup_reassessment_command(
        &self,
        context: &ClinicalContext,
        case_id: Uuid,
        evidence_id: Uuid,
        command_id: Uuid,
    ) -> Result<Option<ReassessEvidenceResult>, ReassessmentError> {
        self.check_reassessment_context(context)?;
        if !self
            .authority
            .may_reassess_evidence(context, case_id, evidence_id)
            .await?
        {
            return Err(ReassessmentError::Denied);
        }
        Ok(self
            .evidence
            .lookup_reassessment_command(context, command_id)
            .await?
            .filter(|result| result.case_id == case_id && result.evidence_id == evidence_id))
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::{
        domain::{ActorId, CaseId, CriterionId, GateAffirmationKind, GateState, PracticeId},
        ports::{
            AuthorityPort, CaseRepository, Clock, CriteriaRepository, Criterion, EvidenceCounts,
            EvidenceRepository, LetterRepository,
        },
        session::UnavailableSessions,
    };
    use async_trait::async_trait;
    use std::sync::{
        Arc, Mutex,
        atomic::{AtomicBool, AtomicUsize, Ordering},
    };

    fn now() -> DateTime<Utc> {
        "2026-09-07T01:00:00Z".parse().unwrap()
    }
    fn id(value: u128) -> Uuid {
        Uuid::from_u128(value)
    }
    fn context(principal: Principal) -> ClinicalContext {
        ClinicalContext {
            identity_id: id(1),
            actor: ActorId(id(2)),
            practice: PracticeId(id(3)),
            principal,
            expires_at: now() + chrono::Duration::hours(1),
        }
    }
    fn command() -> ReassessEvidenceCommand {
        ReassessEvidenceCommand {
            command_id: id(4),
            case_id: id(5),
            evidence_id: id(6),
            state: EvidenceState::Gap,
            expected_assessed_at: now(),
        }
    }
    fn result() -> ReassessEvidenceResult {
        ReassessEvidenceResult {
            command_id: id(4),
            case_id: id(5),
            evidence_id: id(6),
            previous_state: EvidenceState::Void,
            state: EvidenceState::Gap,
            expected_assessed_at: now(),
            assessed_at: now() + chrono::Duration::minutes(1),
        }
    }

    struct FixedClock;
    impl Clock for FixedClock {
        fn now(&self) -> DateTime<Utc> {
            now()
        }
    }

    struct Unused;
    #[async_trait]
    impl CaseRepository for Unused {
        async fn gate_state(&self, _: CaseId) -> Result<GateState, crate::domain::DomainError> {
            panic!("case read")
        }
        async fn record_affirmation(
            &self,
            _: CaseId,
            _: GateAffirmationKind,
            _: ActorId,
            _: DateTime<Utc>,
        ) -> Result<GateState, crate::domain::DomainError> {
            panic!("case write")
        }
    }
    #[async_trait]
    impl CriteriaRepository for Unused {
        async fn get(&self, _: CriterionId) -> Result<Criterion, crate::domain::DomainError> {
            panic!("criterion")
        }
        async fn live_for_payer(
            &self,
            _: &str,
        ) -> Result<Vec<Criterion>, crate::domain::DomainError> {
            panic!("payer")
        }
    }
    #[async_trait]
    impl LetterRepository for Unused {
        async fn get(
            &self,
            _: crate::domain::LetterId,
        ) -> Result<crate::domain::Letter, crate::domain::DomainError> {
            panic!("letter")
        }
        async fn unresolved_non_policy_retrievals(
            &self,
            _: crate::domain::LetterId,
        ) -> Result<Vec<CriterionId>, crate::domain::DomainError> {
            panic!("retrieval")
        }
        async fn sign(
            &self,
            _: crate::domain::LetterId,
            _: ActorId,
            _: DateTime<Utc>,
        ) -> Result<crate::domain::Letter, crate::domain::DomainError> {
            panic!("sign")
        }
    }

    struct ReassessmentPorts {
        allowed: AtomicBool,
        target: Mutex<EvidenceReassessmentTarget>,
        stored: Mutex<Option<ReassessEvidenceResult>>,
        reads: AtomicUsize,
        writes: AtomicUsize,
        lookups: AtomicUsize,
        authority: AtomicUsize,
    }
    #[async_trait]
    impl EvidenceRepository for ReassessmentPorts {
        async fn read_reassessment_target(
            &self,
            _: &ClinicalContext,
            _: Uuid,
            _: Uuid,
        ) -> Result<EvidenceReassessmentTarget, ReassessmentError> {
            self.reads.fetch_add(1, Ordering::SeqCst);
            Ok(*self.target.lock().unwrap())
        }
        async fn execute_reassessment(
            &self,
            _: &ClinicalContext,
            _: &ReassessEvidenceCommand,
        ) -> Result<ReassessEvidenceResult, ReassessmentError> {
            self.writes.fetch_add(1, Ordering::SeqCst);
            Ok(result())
        }
        async fn lookup_reassessment_command(
            &self,
            _: &ClinicalContext,
            _: Uuid,
        ) -> Result<Option<ReassessEvidenceResult>, ReassessmentError> {
            self.lookups.fetch_add(1, Ordering::SeqCst);
            Ok(self.stored.lock().unwrap().clone())
        }
        async fn counts(&self, _: CaseId) -> Result<EvidenceCounts, crate::domain::DomainError> {
            panic!("counts")
        }
    }
    #[async_trait]
    impl AuthorityPort for ReassessmentPorts {
        async fn may_reassess_evidence(
            &self,
            _: &ClinicalContext,
            case_id: Uuid,
            evidence_id: Uuid,
        ) -> Result<bool, ReassessmentError> {
            self.authority.fetch_add(1, Ordering::SeqCst);
            Ok(self.allowed.load(Ordering::SeqCst) && case_id == id(5) && evidence_id == id(6))
        }
        async fn holds(
            &self,
            _: ActorId,
            _: crate::domain::Capability,
        ) -> Result<bool, crate::domain::DomainError> {
            panic!("legacy authority")
        }
    }

    fn fixture() -> (AppServices, Arc<ReassessmentPorts>) {
        let ports = Arc::new(ReassessmentPorts {
            allowed: AtomicBool::new(true),
            target: Mutex::new(EvidenceReassessmentTarget {
                case_id: id(5),
                evidence_id: id(6),
                state: EvidenceState::Void,
                assessed_at: now(),
            }),
            stored: Mutex::new(None),
            reads: AtomicUsize::new(0),
            writes: AtomicUsize::new(0),
            lookups: AtomicUsize::new(0),
            authority: AtomicUsize::new(0),
        });
        let unused = Arc::new(Unused);
        (
            AppServices {
                cases: unused.clone(),
                evidence: ports.clone(),
                criteria: unused.clone(),
                letters: unused,
                authority: ports.clone(),
                clock: Arc::new(FixedClock),
                sessions: Arc::new(UnavailableSessions),
            },
            ports,
        )
    }

    #[tokio::test]
    async fn new_command_checks_revision_and_authority_before_write() {
        let (app, ports) = fixture();
        assert_eq!(
            app.execute_reassess_evidence(&context(Principal::User), &command())
                .await,
            Ok(result()),
        );
        assert_eq!(ports.lookups.load(Ordering::SeqCst), 1);
        assert_eq!(ports.authority.load(Ordering::SeqCst), 2);
        assert_eq!(ports.reads.load(Ordering::SeqCst), 1);
        assert_eq!(ports.writes.load(Ordering::SeqCst), 1);

        ports.target.lock().unwrap().assessed_at = now() + chrono::Duration::seconds(1);
        assert_eq!(
            app.execute_reassess_evidence(&context(Principal::User), &command())
                .await,
            Err(ReassessmentError::RevisionConflict),
        );
        assert_eq!(ports.writes.load(Ordering::SeqCst), 1);
    }

    #[tokio::test]
    async fn stored_result_resolves_without_repeating_the_clinical_write() {
        let (app, ports) = fixture();
        *ports.stored.lock().unwrap() = Some(result());
        assert_eq!(
            app.execute_reassess_evidence(&context(Principal::User), &command())
                .await,
            Ok(result()),
        );
        assert_eq!(ports.reads.load(Ordering::SeqCst), 0);
        assert_eq!(ports.writes.load(Ordering::SeqCst), 0);

        assert_eq!(
            app.execute_reassess_evidence(
                &context(Principal::User),
                &ReassessEvidenceCommand {
                    state: EvidenceState::Met,
                    ..command()
                },
            )
            .await,
            Err(ReassessmentError::CommandConflict),
        );
        assert_eq!(ports.reads.load(Ordering::SeqCst), 0);
        assert_eq!(ports.writes.load(Ordering::SeqCst), 0);
    }

    #[tokio::test]
    async fn nonhuman_and_denied_contexts_never_reach_the_write() {
        let (app, ports) = fixture();
        assert_eq!(
            app.execute_reassess_evidence(&context(Principal::Agent), &command())
                .await,
            Err(ReassessmentError::Denied),
        );
        ports.allowed.store(false, Ordering::SeqCst);
        assert_eq!(
            app.execute_reassess_evidence(&context(Principal::User), &command())
                .await,
            Err(ReassessmentError::Denied),
        );
        assert_eq!(ports.reads.load(Ordering::SeqCst), 0);
        assert_eq!(ports.writes.load(Ordering::SeqCst), 0);
    }

    #[test]
    fn transport_mutation_rejects_caller_selected_authority() {
        let forged = serde_json::json!({
            "commandId": id(4),
            "state": "gap",
            "expectedAssessedAt": now(),
            "actor": id(99),
        });
        assert!(serde_json::from_value::<ReassessEvidenceMutation>(forged).is_err());
    }
}

//! Verified-context letter signing shared by every shell.
//! Identity and practice authority come only from [`ClinicalContext`].

use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};
use uuid::Uuid;

use crate::{
    AppServices,
    affirmation::ClinicalContext,
    domain::{LetterId, LetterStatus},
    session::Principal,
};

/// Transport input. Actor, principal, practice and signature identity are
/// resolved from the fresh verified context and authoritative repository.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct SignLetterMutation {
    pub command_id: Uuid,
    pub expected_letter_version: i32,
    pub expected_qa_revision: i64,
    pub expected_signature_version: i32,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct SignLetterCommand {
    pub command_id: Uuid,
    pub letter_id: LetterId,
    pub expected_letter_version: i32,
    pub expected_qa_revision: i64,
    pub expected_signature_version: i32,
}

/// Authoritative precondition projection. The service checks it before the
/// write; the database checks the underlying rows again while locked.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct SigningTarget {
    pub letter_id: LetterId,
    pub case_id: Uuid,
    pub letter_version: i32,
    pub qa_revision: i64,
    pub signature_version: Option<i32>,
    pub status: LetterStatus,
    pub approved_by_actor: bool,
    pub is_current: bool,
    pub gate_affirmed: bool,
    pub qa_complete: bool,
    pub sources_complete: bool,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct SignLetterResult {
    pub command_id: Uuid,
    pub letter_id: Uuid,
    pub case_id: Uuid,
    pub letter_version: i32,
    pub qa_revision: i64,
    pub signature_id: Uuid,
    pub signature_version: i32,
    pub signed_at: DateTime<Utc>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, thiserror::Error)]
pub enum SigningError {
    #[error("authentication required")]
    Unauthenticated,
    #[error("letter signing denied")]
    Denied,
    #[error("letter not found")]
    NotFound,
    #[error("letter or QA revision is stale")]
    RevisionConflict,
    #[error("signature revision is stale")]
    SignatureConflict,
    #[error("letter is not the current approved revision")]
    NotApproved,
    #[error("case has not been affirmed at the surgeon gate")]
    GateNotAffirmed,
    #[error("letter QA is incomplete or has a blocking failure")]
    QaIncomplete,
    #[error("letter assertions do not have complete sources")]
    SourceIncomplete,
    #[error("command identifier already has a different payload")]
    CommandConflict,
    #[error("letter signing service unavailable")]
    Unavailable,
    #[error("native authentication unavailable")]
    NativeAuthenticationUnavailable,
}

impl AppServices {
    fn check_signing_context(&self, context: &ClinicalContext) -> Result<(), SigningError> {
        if context.expires_at <= self.clock.now() {
            return Err(SigningError::Unauthenticated);
        }
        if context.principal != Principal::User {
            return Err(SigningError::Denied);
        }
        Ok(())
    }

    fn check_signing_target(
        target: &SigningTarget,
        command: &SignLetterCommand,
    ) -> Result<(), SigningError> {
        if target.letter_id != command.letter_id
            || target.letter_version != command.expected_letter_version
            || target.qa_revision != command.expected_qa_revision
        {
            return Err(SigningError::RevisionConflict);
        }
        if target.signature_version != Some(command.expected_signature_version) {
            return Err(SigningError::SignatureConflict);
        }
        if target.status != LetterStatus::Approved
            || !target.approved_by_actor
            || !target.is_current
        {
            return Err(SigningError::NotApproved);
        }
        if !target.gate_affirmed {
            return Err(SigningError::GateNotAffirmed);
        }
        if !target.qa_complete {
            return Err(SigningError::QaIncomplete);
        }
        if !target.sources_complete {
            return Err(SigningError::SourceIncomplete);
        }
        Ok(())
    }

    /// Checks fresh human context, resource authority and every signing
    /// precondition before invoking the repository's independent transaction.
    pub async fn execute_sign_letter(
        &self,
        context: &ClinicalContext,
        command: &SignLetterCommand,
    ) -> Result<SignLetterResult, SigningError> {
        self.check_signing_context(context)?;
        if let Some(original) = self
            .letters
            .lookup_sign_letter_command(context, command.command_id)
            .await?
        {
            if original.command_id != command.command_id
                || original.letter_id != command.letter_id.0
                || original.letter_version != command.expected_letter_version
                || original.qa_revision != command.expected_qa_revision
                || original.signature_version != command.expected_signature_version
            {
                return Err(SigningError::CommandConflict);
            }
            if !self
                .authority
                .may_sign_letter(context, LetterId(original.letter_id))
                .await?
            {
                return Err(SigningError::Denied);
            }
            return Ok(original);
        }
        if !self
            .authority
            .may_sign_letter(context, command.letter_id)
            .await?
        {
            return Err(SigningError::Denied);
        }
        let target = self
            .letters
            .read_signing_target(context, command.letter_id)
            .await?;
        Self::check_signing_target(&target, command)?;
        // Authority and session can change while repository reads wait.
        self.check_signing_context(context)?;
        if !self
            .authority
            .may_sign_letter(context, command.letter_id)
            .await?
        {
            return Err(SigningError::Denied);
        }
        self.letters.execute_sign_letter(context, command).await
    }

    pub async fn lookup_sign_letter_command(
        &self,
        context: &ClinicalContext,
        letter_id: LetterId,
        command_id: Uuid,
    ) -> Result<Option<SignLetterResult>, SigningError> {
        self.check_signing_context(context)?;
        if !self.authority.may_sign_letter(context, letter_id).await? {
            return Err(SigningError::Denied);
        }
        Ok(self
            .letters
            .lookup_sign_letter_command(context, command_id)
            .await?
            .filter(|result| result.letter_id == letter_id.0))
    }

    pub async fn read_signing_target(
        &self,
        context: &ClinicalContext,
        letter_id: LetterId,
    ) -> Result<SigningTarget, SigningError> {
        self.check_signing_context(context)?;
        let target = self.letters.read_signing_target(context, letter_id).await?;
        if target.letter_id != letter_id {
            return Err(SigningError::Unavailable);
        }
        Ok(target)
    }
}

