async fn complete_gate(app: &AppServices, context: &ClinicalContext, case_id: Uuid) {
    for kind in GateAffirmationKind::ALL {
        app.execute_gate_command(
            context,
            &GateCommand {
                command_id: Uuid::new_v4(),
