    mark("service_and_database_refuse_incomplete_qa");

    let missing_source =
        create_letter(&observer, case_id, a.actor.0, 3, true, SourceFixture::None).await;
    let source_target = app
        .read_signing_target(&a, LetterId(missing_source))
