    assert_eq!(
        repository.execute_sign_letter(&a, &source_command).await,
        Err(SigningError::SourceIncomplete)
    );
    mark("service_and_database_refuse_incomplete_sources");

    let annotation_only = create_letter(
        &observer,
        case_id,
        a.actor.0,
        4,
        true,
        SourceFixture::Annotation,
    )
    .await;
    let annotation_target = app
        .read_signing_target(&a, LetterId(annotation_only))
        .await
        .unwrap();
    assert!(annotation_target.qa_complete && !annotation_target.sources_complete);
    let annotation_command = command(&annotation_target);
    assert_eq!(
