//! Explicit deployment operation. Ordinary server startup never reads migration
//! credentials or runs DDL. The existing ASO schema is a prerequisite.

use sqlx::{
    PgPool,
    migrate::{Migration, MigrationSource, MigrationType, Migrator},
    postgres::PgPoolOptions,
};
use std::{future::Future, pin::Pin};

#[derive(Debug)]
struct ServerMigrations;

impl MigrationSource<'static> for ServerMigrations {
    fn resolve(
        self,
    ) -> Pin<Box<dyn Future<Output = Result<Vec<Migration>, sqlx::error::BoxDynError>> + Send>>
    {
        Box::pin(async {
            Ok(vec![
                Migration::new(
                    2026090600,
                    "local publication boundary".into(),
                    MigrationType::Simple,
                    include_str!(
                        "../../../migrations/server/2026090600_local_publication_boundary.sql"
                    )
                    .into(),
                    false,
                ),
                Migration::new(
                    2026090601,
                    "durable gate".into(),
                    MigrationType::Simple,
                    include_str!("../../../migrations/server/2026090601_durable_gate.sql").into(),
                    false,
                ),
                Migration::new(
                    2026090602,
                    "durable signing".into(),
                    MigrationType::Simple,
                    include_str!("../../../migrations/server/2026090602_durable_signing.sql")
                        .into(),
                    false,
                ),
                Migration::new(
                    2026090603,
                    "durable evidence reassessment".into(),
                    MigrationType::Simple,
                    include_str!("../../../migrations/server/2026090603_durable_reassessment.sql")
                        .into(),
                    false,
                ),
                Migration::new(
                    2026090604,
                    "immutable approved source documents".into(),
                    MigrationType::Simple,
                    include_str!(
                        "../../../migrations/server/2026090604_immutable_approved_sources.sql"
                    )
                    .into(),
                    false,
                ),
                Migration::new(
                    2026090605,
                    "clinical revision and publication guards".into(),
                    MigrationType::Simple,
                    include_str!(
                        "../../../migrations/server/2026090605_clinical_revision_guards.sql"
                    )
                    .into(),
                    false,
                ),
            ])
        })
    }
}

async fn reject_unsafe_local_publications(pool: &PgPool) -> Result<(), Box<dyn std::error::Error>> {
    let unsafe_publication: bool = sqlx::query_scalar(
        "SELECT EXISTS (SELECT FROM pg_catalog.pg_publication WHERE puballtables)
          OR EXISTS (
            SELECT FROM pg_catalog.pg_publication_namespace pn
            JOIN pg_catalog.pg_namespace n ON n.oid = pn.pnnspid
            WHERE n.nspname = 'aso'
          )
          OR EXISTS (
            SELECT FROM pg_catalog.pg_publication_rel pr
            JOIN pg_catalog.pg_class c ON c.oid = pr.prrelid
            JOIN pg_catalog.pg_namespace n ON n.oid = c.relnamespace
            WHERE c.relname IN (
                    'gate_commands',
                    'letter_sign_commands',
                    'evidence_reassessment_commands'
                  )
               OR (
                 position('Privacy: local' in COALESCE(
                   pg_catalog.obj_description(c.oid, 'pg_class'), '')) > 0
                 AND position('excluded from replication' in COALESCE(
                   pg_catalog.obj_description(c.oid, 'pg_class'), '')) > 0
               )
          )",
    )
    .fetch_one(pool)
    .await
    .map_err(|_| "server migration publication preflight failed")?;
    if unsafe_publication {
        return Err(
            "server migration requires explicit-table publications that exclude local command ledgers; repair the publication, verify that local command data was not replicated, and rerun"
                .into(),
        );
    }
    Ok(())
}

pub async fn run() -> Result<(), Box<dyn std::error::Error>> {
    let url = std::env::var("ASO_MIGRATION_DATABASE_URL")
        .map_err(|_| "ASO_MIGRATION_DATABASE_URL is required for --migrate-server")?;
    let pool = PgPoolOptions::new()
        .max_connections(1)
        .connect(&url)
        .await
        .map_err(|_| "server migration connection failed")?;
    // All server migrations commit separately. Refuse an already unsafe
    // publication, then install the publication boundary as migration 0600
    // before any local command table can commit. Existing databases apply the
    // same lower-numbered missing migration before later pending versions.
    reject_unsafe_local_publications(&pool).await?;
    // SQLx takes its migration lock, validates SHA-384 checksums, and commits
    // each migration and its ledger entry in one transaction.
    let result = Migrator::new(ServerMigrations).await?.run(&pool).await;
    if result.is_ok()
        && let Err(error) = reject_unsafe_local_publications(&pool).await
    {
        pool.close().await;
        return Err(error);
    }
    pool.close().await;
    match result {
        Ok(()) => {
            println!("server migrations applied and checksums verified");
            Ok(())
        }
        Err(sqlx::migrate::MigrateError::VersionMismatch(_)) => {
            Err("server migration checksum mismatch: applied SQL was modified".into())
        }
        // SQL errors can contain record values. Keep deployment output generic.
        Err(_) => {
            Err("server migration failed; database unchanged for the failed migration".into())
        }
    }
}

//! Tauri desktop shell.
//!
//! The shell owns windowing and IPC. It owns no domain logic: every command
//! below is a thin call into [`aso_host::AppServices`], the same services the
//! Axum binary and the Flutter bridge consume.
//!
//! Two rules this file exists to hold:
//!   * Domain logic never migrates here to "just make the desktop work". If a
//!     rule is needed on desktop it is needed everywhere, so it belongs in the
//!     host crate.
//!   * The custom title bar is a DESKTOP concern. The same React bundle serves
//!     the browser, where the OS draws no window controls — so the title bar is
//!     conditionally rendered on the web side, never unconditionally imported.

use std::sync::Arc;

use aso_host::AppServices;

pub struct DesktopState {
    pub services: Arc<AppServices>,
}

/// Commands mirror the HTTP routes one-for-one so the React client can target
/// either transport without a second data model.
pub mod commands {
    use super::*;
    use aso_host::affirmation::{GateCommandResult, GateError, GateMutation, GateSnapshot};
    use aso_host::reassessment::{
        ReassessEvidenceMutation, ReassessEvidenceResult, ReassessmentError,
    };
    use aso_host::signing::{SignLetterMutation, SignLetterResult, SigningError};
    use uuid::Uuid;

    /// Mirrors GET /api/session. Native credentials have no owner until ra-17;
    /// an IPC caller cannot substitute identity, capabilities or a token here.
    pub async fn current_session(
        _state: &DesktopState,
        _practice_id: Option<uuid::Uuid>,
    ) -> Result<aso_host::session::SessionSummary, aso_host::session::SessionError> {
        Err(aso_host::session::SessionError::NativeAuthenticationUnavailable)
    }

    /// Mirrors the gate routes. Native credentials have no trusted owner until
    /// ra-17, so no gate command can derive authority from IPC arguments.
    pub async fn gate_state(
        _state: &DesktopState,
        _case_id: Uuid,
        _practice_id: Option<Uuid>,
    ) -> Result<GateSnapshot, GateError> {
        Err(GateError::NativeAuthenticationUnavailable)
    }

    pub async fn affirm_gate(
        _state: &DesktopState,
        _case_id: Uuid,
        _practice_id: Option<Uuid>,
        _request: GateMutation,
    ) -> Result<GateCommandResult, GateError> {
        Err(GateError::NativeAuthenticationUnavailable)
    }

