import { useCallback, useEffect, useRef, useState } from 'react';

import { useLocalStore } from '../../../app/providers/graph-provider';
import { ApiError } from '../../../shared/api/http-client';
import type { EvidenceState } from '../../../shared/model/evidence-state';
import type { ReassessEvidenceResult, TimelineEntry } from '../model/timeline-entry';
import { readTimeline, timelineApi } from '../api/timeline-api';

// What components import. It owns loading, error and intent-shaped operations;
// components render, they do not orchestrate.
//
// No query cache (ADR-001). The local store is kept current by Electric, so
// "is this stale?" is already answered one layer down.

export interface UseEvidenceTimeline {
  entries: readonly TimelineEntry[];
  loading: boolean;
  /** The store is not open yet. Distinct from `loading` — nothing was asked. */
  unavailable: boolean;
  /** Set when a read failed. The screen shows this rather than an empty list. */
  error: string | null;
  /** Present when a write was REFUSED — e.g. the caller lacks the capability. */
  refusal: string | null;
  /** Retained when a transport result is uncertain so lookup can reconcile it. */
  lastCommandId: string | null;
  /** True while one reassessment request owns the mutation slot. */
  submitting: boolean;
  reassess: (entryId: string, state: EvidenceState) => Promise<void>;
  lookupCommand: (entryId: string, commandId: string) => Promise<ReassessEvidenceResult>;
}

type TimelineView = Pick<
  UseEvidenceTimeline,
  'entries' | 'loading' | 'error' | 'refusal' | 'lastCommandId' | 'submitting'
>;

function initialView(caseId: string) {
  return {
    scope: { caseId },
    entries: [] as readonly TimelineEntry[],
    loading: true,
    error: null as string | null,
    refusal: null as string | null,
    lastCommandId: null as string | null,
    submitting: false,
  };
}

export function useEvidenceTimeline(caseId: string): UseEvidenceTimeline {
  const db = useLocalStore();
  const pendingCommand = useRef<{ scope: object; id: string } | null>(null);
  const [storedView, setView] = useState(() => initialView(caseId));
  let view = storedView;
  if (view.scope.caseId !== caseId) {
    // Clear the previous case before any new-case render can expose its rows,
    // refusal or uncertain command correlation.
    view = initialView(caseId);
    pendingCommand.current = null;
    setView(view);
  }
  const { scope, entries, loading, error, refusal, lastCommandId, submitting } = view;
  const update = useCallback(
    (patch: Partial<TimelineView>) => {
      // Scope object identity also fences a late completion after A -> B -> A.
      setView((current) => (current.scope === scope ? { ...current, ...patch } : current));
    },
    [scope],
  );

  useEffect(() => {
    if (!db) return;

    let live = true;
    readTimeline(db, scope.caseId)
      .then((rows) => {
        if (!live) return;
        update({ entries: rows, error: null });
      })
      .catch((e: unknown) => {
        // An empty list and a failed read look identical on screen, and one of
        // them means "no evidence recorded" while the other means "we do not
        // know". Never let a failure render as the former.
        if (live) update({ error: e instanceof Error ? e.message : String(e) });
      })
      .finally(() => {
        if (live) update({ loading: false });
      });

    return () => {
      live = false;
    };
  }, [db, scope, update]);

  const reassess = useCallback(
    async (entryId: string, state: EvidenceState) => {
      const entry = entries.find((candidate) => candidate.id === entryId);
      if (!entry?.assessedAt) {
        throw new Error('The current evidence assessment revision is unavailable.');
      }
      if (pendingCommand.current?.scope === scope) {
        throw new Error('An evidence reassessment is already pending.');
      }
      const commandId = crypto.randomUUID();
      const pending = { scope, id: commandId };
      pendingCommand.current = pending;
      update({ submitting: true, lastCommandId: null, refusal: null });
      try {
        await timelineApi.reassess(
          scope.caseId,
          entryId,
          commandId,
          state,
          entry.assessedAt,
        );
        if (pendingCommand.current === pending) {
          pendingCommand.current = null;
          update({ submitting: false, lastCommandId: null });
        }
      } catch (e) {
        // A refusal is information the coordinator needs, not an exception to
        // swallow. It tells them who must act instead.
        if (pendingCommand.current === pending) {
          pendingCommand.current = null;
          if (e instanceof ApiError) {
            if (e.isCapabilityDenied || e.isPreconditionUnmet) {
              update({ submitting: false, refusal: e.message, lastCommandId: null });
              return;
            }
            update({
              submitting: false,
              lastCommandId: e.isCommitOutcomeUncertain ? commandId : null,
            });
          } else {
            update({ submitting: false, lastCommandId: commandId });
          }
        }
        if (e instanceof ApiError && (e.isCapabilityDenied || e.isPreconditionUnmet)) {
          return;
        }
        throw e;
      }
    },
    [entries, scope, update],
  );

  const lookupCommand = useCallback(
    async (entryId: string, commandId: string) => {
      const receipt = await timelineApi.lookupCommand(scope.caseId, entryId, commandId);
      setView((current) =>
        current.scope === scope && current.lastCommandId === commandId
          ? { ...current, lastCommandId: null }
          : current,
      );
      return receipt;
    },
    [scope, update],
  );

  return {
    entries,
    loading,
    unavailable: db === null,
    error,
    refusal,
    lastCommandId,
    submitting,
    reassess,
    lookupCommand,
  };
}

import { httpClient } from '../../../shared/api/http-client';
import type { GateCommandResult, GateMutation, GateSnapshot } from '../model/gate-state';

// Feature API modules are the only callers of the http client. They translate
// transport shapes into feature model types and nothing else — no React, no
// component state.

function gatePath(caseId: string, suffix: string, practiceId?: string): string {
  const selection = practiceId ? `?practiceId=${encodeURIComponent(practiceId)}` : '';
  return `/api/cases/${encodeURIComponent(caseId)}/gate${suffix}${selection}`;
}

export const gateApi = {
  read: (caseId: string, practiceId?: string) =>
    httpClient.get<GateSnapshot>(gatePath(caseId, '', practiceId)),

  affirm: (caseId: string, request: GateMutation, practiceId?: string) =>
    httpClient.post<GateCommandResult>(gatePath(caseId, '/affirm', practiceId), request),

  remove: (caseId: string, request: GateMutation, practiceId?: string) =>
    httpClient.post<GateCommandResult>(gatePath(caseId, '/remove', practiceId), request),

  lookupCommand: (caseId: string, commandId: string, practiceId?: string) =>
    httpClient.get<GateCommandResult>(
      gatePath(caseId, `/commands/${encodeURIComponent(commandId)}`, practiceId),
    ),
};

