  it.each(['success', 'refusal'])('fences a late mutation %s after leaving and returning to a scope', async (outcome) => {
    const { result, rerender } = renderHook(
      ({ selectedPractice }) => useSurgeonGate(caseId, { practiceId: selectedPractice }),
      { initialProps: { selectedPractice: practiceId } },
    );
    await waitFor(() => expect(result.current.loading).toBe(false));
    const pending = deferred<GateCommandResult>();
    vi.mocked(httpClient.post).mockReturnValueOnce(pending.promise);
    let mutation!: Promise<void>;
    act(() => { mutation = result.current.remove('plan'); });
    rerender({ selectedPractice: 'next-practice' });
    await waitFor(() => expect(result.current.loading).toBe(false));
    rerender({ selectedPractice: practiceId });
    await waitFor(() => expect(result.current.loading).toBe(false));
    await act(async () => {
      if (outcome === 'success') pending.resolve(receipt('synthetic', 'remove'));
      else pending.reject(new ApiError(403, 'Old refusal'));
      await mutation;
    });
    expect(result.current).toMatchObject({
      state: { affirmed: true, outstanding: [] }, error: null, refusal: null, lastCommandId: null,
      submitting: false,
    });
  });

  it.each(['receipt', 'refresh'])('fences a late lookup %s after a practice switch', async (stage) => {
    const { result, rerender } = renderHook(
      ({ selectedPractice }) => useSurgeonGate(caseId, { practiceId: selectedPractice }),
      { initialProps: { selectedPractice: practiceId } },
    );
    await waitFor(() => expect(result.current.loading).toBe(false));
    const pendingReceipt = deferred<GateCommandResult>();
    const pendingRead = deferred<GateSnapshot>();
    const committed = receipt('synthetic', 'remove');
    vi.mocked(httpClient.get).mockReturnValueOnce(pendingReceipt.promise);
    let lookup!: Promise<GateCommandResult>;
    act(() => { lookup = result.current.lookupCommand(committed.commandId); });
    if (stage === 'refresh') {
      vi.mocked(httpClient.get).mockReturnValueOnce(pendingRead.promise);
      await act(async () => pendingReceipt.resolve(committed));
    }
    rerender({ selectedPractice: 'next-practice' });
    await waitFor(() => expect(result.current.loading).toBe(false));
    await act(async () => {
      if (stage === 'receipt') {
        vi.mocked(httpClient.get).mockResolvedValueOnce(committed.gate);
        pendingReceipt.resolve(committed);
      } else {
        pendingRead.resolve(committed.gate);
      }
      expect(await lookup).toEqual(committed);
    });
    expect(result.current).toMatchObject({
      state: { affirmed: true, outstanding: [] }, error: null, refusal: null, lastCommandId: null,
    });
  });

  it('clears a prior read error when the practice changes', async () => {
    vi.mocked(httpClient.get).mockRejectedValueOnce(new Error('Old read failed'));
    const { result, rerender } = renderHook(
      ({ selectedPractice }) => useSurgeonGate(caseId, { practiceId: selectedPractice }),
      { initialProps: { selectedPractice: practiceId } },
    );
    await waitFor(() => expect(result.current.error).toBe('Old read failed'));
    const nextRead = deferred<GateSnapshot>();
    vi.mocked(httpClient.get).mockReturnValueOnce(nextRead.promise);
    rerender({ selectedPractice: 'next-practice' });
    expect(result.current).toMatchObject({ state: null, error: null, loading: true });
    await act(async () => nextRead.resolve(snapshot));
  });

  it('refuses a duplicate gate mutation while the first command is pending', async () => {
    const { result } = renderHook(() => useSurgeonGate(caseId));
    await waitFor(() => expect(result.current.loading).toBe(false));
    const pending = deferred<GateCommandResult>();
    vi.mocked(httpClient.post).mockReturnValueOnce(pending.promise);

    let first!: Promise<void>;
    act(() => {
      first = result.current.remove('plan');
    });
    expect(result.current.submitting).toBe(true);
    expect(result.current.lastCommandId).toBeNull();
    await expect(result.current.affirm('plan')).rejects.toThrow('A gate command is already pending.');
    expect(httpClient.post).toHaveBeenCalledTimes(1);

    await act(async () => {
      pending.resolve(receipt('55555555-5555-4555-8555-555555555555', 'remove'));
      await first;
    });
    expect(result.current.submitting).toBe(false);
    expect(result.current.lastCommandId).toBeNull();
  });
});

import { useCallback, useEffect, useRef, useState } from 'react';

import { ApiError } from '../../../shared/api/http-client';
import { gateApi } from '../api/gate-api';
import { gateStateFromSnapshot } from '../model/gate-state';
import type { GateAffirmationKind, GateCommandResult, GateState } from '../model/gate-state';

// The feature hook is what components import. It owns loading, error and
// intent-shaped operations; components render, they do not orchestrate.
//
// No query cache. A synced local store already knows freshness — see
// docs/architecture/adr-001-no-query-cache.md.

interface UseSurgeonGate {
  state: GateState | null;
  loading: boolean;
  /**
   * Set when the READ failed. Distinct from `state === null` after a
   * successful read, and the caller must render it differently.
   *
   * Without this, a 500 or a dropped connection leaves `state` null with
   * `loading` false, and any caller writing `state?.affirmed ?? false` — the
   * natural reading — shows an AFFIRMED case as unaffirmed. That is a runtime
   * failure masquerading as domain state, which ADR-003 forbids: loading,
   * offline and error are runtime states, never additional evidence states.
   */
  error: string | null;
  /** Present when the last affirmation was REFUSED — e.g. by an administrator. */
  refusal: string | null;
  /** Retained after an uncertain response for explicit command lookup. */
  lastCommandId: string | null;
  /** True while one gate command owns the mutation slot. */
  submitting: boolean;
  affirm: (kind: GateAffirmationKind) => Promise<void>;
  remove: (kind: GateAffirmationKind) => Promise<void>;
  lookupCommand: (commandId: string) => Promise<GateCommandResult>;
}

interface SurgeonGateScope {
  practiceId?: string;
}

type GateView = Pick<
  UseSurgeonGate,
  'state' | 'loading' | 'error' | 'refusal' | 'lastCommandId' | 'submitting'
>;

function initialView(caseId: string, practiceId?: string) {
  return {
    scope: { caseId, practiceId },
    state: null as GateState | null,
    loading: true,
    error: null as string | null,
    refusal: null as string | null,
    lastCommandId: null as string | null,
    submitting: false,
  };
}

export function useSurgeonGate(caseId: string, options?: SurgeonGateScope): UseSurgeonGate {
  const practiceId = options?.practiceId;
  const pendingCommand = useRef<{ scope: object; id: string } | null>(null);
  const [storedView, setView] = useState(() => initialView(caseId, practiceId));
  let view = storedView;
  if (view.scope.caseId !== caseId || view.scope.practiceId !== practiceId) {
    // Reset before exposing another case/practice's data, even for one render.
    view = initialView(caseId, practiceId);
    pendingCommand.current = null;
    setView(view);
  }
  const { scope, state, loading, error, refusal, lastCommandId, submitting } = view;
  const update = useCallback((patch: Partial<GateView>) => {
    // Scope identity also fences a late response after A -> B -> A navigation.
    setView((current) => current.scope === scope ? { ...current, ...patch } : current);
  }, [scope]);

  useEffect(() => {
    let live = true;
    gateApi
      .read(scope.caseId, scope.practiceId)
      .then((s) => {
        if (!live) return;
        update({ state: gateStateFromSnapshot(s), error: null });
      })
      .catch((e: unknown) => {
        // The gate is the highest-stakes read in the product. A swallowed
        // failure here is indistinguishable from "not affirmed".
        if (live) update({ error: e instanceof Error ? e.message : String(e) });
      })
      .finally(() => live && update({ loading: false }));
    return () => {
      live = false;
    };
  }, [scope, update]);

  const mutate = useCallback(
    async (action: 'affirm' | 'remove', kind: GateAffirmationKind) => {
      if (pendingCommand.current?.scope === scope) {
        throw new Error('A gate command is already pending.');
      }
      const commandId = crypto.randomUUID();
      const pending = { scope, id: commandId };
      pendingCommand.current = pending;
      update({ submitting: true, lastCommandId: null, refusal: null });
      try {
        const result = await gateApi[action](
          scope.caseId,
          { commandId, kind },
          scope.practiceId,
        );
        if (pendingCommand.current === pending) {
          pendingCommand.current = null;
          update({
            state: gateStateFromSnapshot(result.gate),
            submitting: false,
            lastCommandId: null,
          });
        }
      } catch (e) {
        // A refusal is information the user needs, not an exception to swallow.
        // "You may not affirm this" tells a coordinator exactly what to do next.
        if (pendingCommand.current === pending) {
          pendingCommand.current = null;
          if (e instanceof ApiError) {
            if (e.isCapabilityDenied || e.isPreconditionUnmet) {
              update({ submitting: false, refusal: e.message, lastCommandId: null });
              return;
            }
            update({
              submitting: false,
              lastCommandId: e.isCommitOutcomeUncertain ? commandId : null,
            });
          } else {
            update({ submitting: false, lastCommandId: commandId });
          }
        }
        if (e instanceof ApiError && (e.isCapabilityDenied || e.isPreconditionUnmet)) {
          return;
        }
        throw e;
      }
    },
    [scope, update],
  );

  const affirm = useCallback((kind: GateAffirmationKind) => mutate('affirm', kind), [mutate]);
  const remove = useCallback((kind: GateAffirmationKind) => mutate('remove', kind), [mutate]);
  const lookupCommand = useCallback(
    async (commandId: string) => {
      const receipt = await gateApi.lookupCommand(scope.caseId, commandId, scope.practiceId);
      setView((current) =>
        current.scope === scope && current.lastCommandId === commandId
          ? { ...current, lastCommandId: null }
          : current,
      );
      try {
        // A receipt is historical: refresh the current gate after recovery.
        const current = await gateApi.read(scope.caseId, scope.practiceId);
        update({ state: gateStateFromSnapshot(current), error: null });
      } catch (e) {
        update({ state: null, error: e instanceof Error ? e.message : String(e) });
      }
      return receipt;
    },
    [scope, update],
  );

  return {
    state,
    loading,
    error,
    refusal,
    lastCommandId,
    submitting,
    affirm,
    remove,
    lookupCommand,
  };
}

// The ONLY place in the web app that calls fetch.
//
// Components import feature hooks; hooks call a feature api module; a feature
// api module calls this. A component that reaches for fetch has skipped two
// layers, and scripts/audit.sh fails the build when one does.

const BASE = import.meta.env.VITE_API_BASE ?? '';

export class ApiError extends Error {
  constructor(
    readonly status: number,
    message: string,
  ) {
    super(message);
    this.name = 'ApiError';
  }

  /** 403 on a clinical act is a real answer, not a bug. Surface the reason. */
  get isCapabilityDenied() {
    return this.status === 403;
  }

  /** 409 means an upstream precondition is unmet — the gate, usually. */
  get isPreconditionUnmet() {
    return this.status === 409;
  }

  /** The command may have committed before an upstream timeout or failure. */
  get isCommitOutcomeUncertain() {
    return this.status === 408 || this.status >= 500;
  }
}

async function request<T>(path: string, init?: RequestInit): Promise<T> {
  const res = await fetch(`${BASE}${path}`, {
    ...init,
    headers: { 'content-type': 'application/json', ...init?.headers },
  });

  if (!res.ok) {
    const body = (await res.json().catch(() => ({}))) as { error?: string };
    throw new ApiError(res.status, body.error ?? res.statusText);
  }
  return (await res.json()) as T;
}

export const httpClient = {
  get: <T>(path: string) => request<T>(path),
  post: <T>(path: string, body: unknown) =>
    request<T>(path, { method: 'POST', body: JSON.stringify(body) }),
};
